import{_ as l,o as e,c as i,ae as r}from"./chunks/framework.RRduUuAx.js";const c=JSON.parse('{"title":"返金（明細の返金）","description":"","frontmatter":{},"headers":[],"relativePath":"v1/ja/guide/10-bill-refund-guide.md","filePath":"v1/ja/guide/10-bill-refund-guide.md"}'),t={name:"v1/ja/guide/10-bill-refund-guide.md"};function o(d,a,h,n,u,s){return e(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="返金-明細の返金" tabindex="-1">返金（明細の返金） <a class="header-anchor" href="#返金-明細の返金" aria-label="Permalink to &quot;返金（明細の返金）&quot;">​</a></h1><h2 id="_1-この機能について" tabindex="-1">1. この機能について <a class="header-anchor" href="#_1-この機能について" aria-label="Permalink to &quot;1. この機能について&quot;">​</a></h2><p>「返金」は、明細が返金されたときの入出金を記録し、集計上の金額影響を自動で相殺するための機能です。</p><p>Koala では、元の明細をもとに「負の金額」の返金明細を新しく追加します。</p><ul><li>元の明細が支出の場合：返金明細も「支出」ですが、金額はマイナスになり、元の支出を相殺します</li><li>元の明細が収入の場合：返金明細も「収入」ですが、金額はマイナスになり、元の収入を相殺します</li></ul><p>また、返金明細には自動で「返金」タグが付くため、後から探しやすくなります。</p><h2 id="_2-こんなときに便利" tabindex="-1">2. こんなときに便利 <a class="header-anchor" href="#_2-こんなときに便利" aria-label="Permalink to &quot;2. こんなときに便利&quot;">​</a></h2><ul><li>購入の返金・返品の返金</li><li>一部返金</li><li>入金の取り消し（例：振込の取消、入金の差し戻し）</li></ul><h2 id="_3-使い方" tabindex="-1">3. 使い方 <a class="header-anchor" href="#_3-使い方" aria-label="Permalink to &quot;3. 使い方&quot;">​</a></h2><ol><li>明細一覧で返金したい明細を見つける</li><li>その明細を左にスワイプして「返金」を選ぶ</li><li>返金画面で設定する： <ul><li>金額：初期値は元の金額。部分返金の場合は変更できます</li><li>日付：初期値は今日。必要に応じて実際の返金日へ変更します</li><li>タグ：元のタグを引き継ぎ、さらに「返金」タグが自動で追加されます</li><li>メモ：任意</li></ul></li><li>「確定/完了」をタップして保存</li></ol><p>保存後、一覧に返金明細が追加され、該当金額の影響が相殺されます。</p><h2 id="_4-ルールと注意点" tabindex="-1">4. ルールと注意点 <a class="header-anchor" href="#_4-ルールと注意点" aria-label="Permalink to &quot;4. ルールと注意点&quot;">​</a></h2><ul><li>返金された実額を入力してください。マイナス記号を手動で付ける必要はありません。</li><li>支出の返金・収入の返金はどちらも「負の金額」で記録されるため、集計で自動的に相殺されます。</li><li>複数回の返金に対応しています。同じ明細が複数回に分かれて返金された場合、都度返金操作を行い、返金明細を複数作成できます。</li><li>返金明細を削除すると相殺効果もなくなり、集計は返金前の状態に戻ります。</li></ul><h2 id="_5-よくある質問" tabindex="-1">5. よくある質問 <a class="header-anchor" href="#_5-よくある質問" aria-label="Permalink to &quot;5. よくある質問&quot;">​</a></h2><h3 id="q1-一部返金はどう記録しますか" tabindex="-1">Q1：一部返金はどう記録しますか？ <a class="header-anchor" href="#q1-一部返金はどう記録しますか" aria-label="Permalink to &quot;Q1：一部返金はどう記録しますか？&quot;">​</a></h3><p>返金画面で金額を実際の返金額に変更してください。複数回に分けて返金することも可能です。</p><h3 id="q2-返金は元の明細を変更しますか" tabindex="-1">Q2：返金は元の明細を変更しますか？ <a class="header-anchor" href="#q2-返金は元の明細を変更しますか" aria-label="Permalink to &quot;Q2：返金は元の明細を変更しますか？&quot;">​</a></h3><p>元の明細の金額は変更されません。返金は「返金明細を追加する」方式なので、元の支出/収入を残しつつ、集計を説明可能な形で相殺できます。</p><h3 id="q3-返金だけをまとめて確認できますか" tabindex="-1">Q3：返金だけをまとめて確認できますか？ <a class="header-anchor" href="#q3-返金だけをまとめて確認できますか" aria-label="Permalink to &quot;Q3：返金だけをまとめて確認できますか？&quot;">​</a></h3><p>返金明細には自動で「返金」タグが付くため、タグでフィルタ/検索して確認できます。</p>',20)])])}const p=l(t,[["render",o]]);export{c as __pageData,p as default};
